<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Top-Down Billiards</title>
<style>
  * { box-sizing: border-box; }
  html, body {
    margin: 0; padding: 0; height: 100%;
    background: radial-gradient(ellipse at center, #3a3a3a 0%, #151515 100%);
    color: #eee;
    font-family: 'Segoe UI', Arial, sans-serif;
    display: flex; flex-direction: column; align-items: center;
    padding: 14px 0 30px;
  }
  h1 { margin: 6px 0 2px; font-size: 22px; letter-spacing: 1px; color: #f0d98a; }
  #tableWrap {
    margin-top: 6px;
    filter: drop-shadow(0 10px 25px rgba(0,0,0,0.6));
  }
  canvas {
    display: block;
    border-radius: 14px;
    max-width: 92vw;
    height: auto;
    touch-action: none;
    cursor: crosshair;
  }
  .panel {
    margin-top: 14px;
    display: flex;
    gap: 14px;
    align-items: center;
    flex-wrap: wrap;
    justify-content: center;
  }
  button {
    padding: 10px 22px;
    font-size: 15px;
    font-weight: 600;
    border: none;
    border-radius: 8px;
    background: linear-gradient(#5fd06a,#2f9e42);
    color: #06280a;
    cursor: pointer;
    box-shadow: 0 3px 0 #1b6a29;
  }
  button:active { transform: translateY(2px); box-shadow: 0 1px 0 #1b6a29; }
  .instructions {
    max-width: 720px;
    margin-top: 12px;
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.15);
    padding: 12px 18px;
    border-radius: 10px;
    font-size: 14px;
    line-height: 1.5;
    text-align: center;
  }
  .instructions b { color: #f0d98a; }
  #status {
    margin-top: 6px;
    font-size: 13px;
    color: #9fd39f;
    min-height: 18px;
  }
</style>
</head>
<body>

<h1>🎱 Top-Down Billiards</h1>

<div id="tableWrap">
  <canvas id="table"></canvas>
</div>

<div class="panel">
  <button id="resetBtn">Reset / Rack</button>
</div>

<div id="status"></div>

<div class="instructions">
  <b>How to play:</b> Click and hold on the <b>white cue ball</b>, then drag <b>away</b>
  from it to aim — the ball will fire in the opposite direction of your drag, like pulling
  back a slingshot. Drag further for more power. Release the mouse button to strike the ball.
  Use <b>Reset / Rack</b> to set the balls back into a fresh triangle formation.
</div>

<script>
(function(){
  "use strict";

  // ---------------------------------------------------------------
  // Constants / table geometry
  // ---------------------------------------------------------------
  const W = 800, H = 400;      // playfield size (px)
  const R = 11;                 // ball radius (px)
  const RAIL = 30;               // wooden rail thickness (px) - drawing only
  const POCKET_R = R * 1.9;
  const FRICTION = 360;          // deceleration px/s^2 (rolling friction)
  const WALL_RESTITUTION = 0.85;
  const BALL_RESTITUTION = 0.98;
  const MAX_DRAG = 170;          // px
  const POWER_SCALE = 14;        // px/s of ball speed per px of drag

  const POCKETS = [
    {x:0,     y:0},
    {x:W/2,   y:0},
    {x:W,     y:0},
    {x:0,     y:H},
    {x:W/2,   y:H},
    {x:W,     y:H}
  ];

  const BALL_COLORS = [
    '#e6c619','#1e4fd8','#d0281c','#6a1e9c','#e07b18',
    '#1f7a34','#8a1c2c','#1a1a1a','#e6c619','#1e4fd8',
    '#d0281c','#6a1e9c','#e07b18','#1f7a34','#8a1c2c'
  ];

  // ---------------------------------------------------------------
  // Canvas setup
  // ---------------------------------------------------------------
  const canvas = document.getElementById('table');
  const ctx = canvas.getContext('2d');
  canvas.width = W + RAIL * 2;
  canvas.height = H + RAIL * 2;

  // ---------------------------------------------------------------
  // Ball state
  // ---------------------------------------------------------------
  let balls = []; // {x,y,vx,vy,potted,cue,r}

  function makeBall(b){
    return {
      x: b.x, y: b.y,
      vx: b.vx || 0, vy: b.vy || 0,
      potted: false,
      cue: !!b.cue,
      r: R
    };
  }

  // ---------------------------------------------------------------
  // Physics
  // ---------------------------------------------------------------
  function substep(dt){
    // motion + friction
    for(const b of balls){
      if(b.potted) continue;
      const speed = Math.hypot(b.vx, b.vy);
      if(speed > 0){
        let newSpeed = speed - FRICTION * dt;
        if(newSpeed < 0.5) newSpeed = 0;
        const scale = newSpeed / speed;
        b.vx *= scale; b.vy *= scale;
      }
      b.x += b.vx * dt;
      b.y += b.vy * dt;
    }

    // wall / cushion collisions
    for(const b of balls){
      if(b.potted) continue;
      if(b.x < b.r){ b.x = b.r; b.vx = -b.vx * WALL_RESTITUTION; }
      if(b.x > W - b.r){ b.x = W - b.r; b.vx = -b.vx * WALL_RESTITUTION; }
      if(b.y < b.r){ b.y = b.r; b.vy = -b.vy * WALL_RESTITUTION; }
      if(b.y > H - b.r){ b.y = H - b.r; b.vy = -b.vy * WALL_RESTITUTION; }
    }

    // ball-ball collisions
    for(let i = 0; i < balls.length; i++){
      const a = balls[i];
      if(a.potted) continue;
      for(let j = i + 1; j < balls.length; j++){
        const b = balls[j];
        if(b.potted) continue;
        resolveCollision(a, b);
      }
    }

    // pockets
    for(const b of balls){
      if(b.potted) continue;
      for(const p of POCKETS){
        const dx = b.x - p.x, dy = b.y - p.y;
        if(dx*dx + dy*dy < POCKET_R * POCKET_R){
          b.potted = true;
          b.vx = 0; b.vy = 0;
          break;
        }
      }
    }
  }

  function resolveCollision(a, b){
    const dx = b.x - a.x, dy = b.y - a.y;
    const dist = Math.hypot(dx, dy);
    const minDist = a.r + b.r;
    if(dist === 0 || dist >= minDist) return;

    const nx = dx / dist, ny = dy / dist;

    // separate overlap equally
    const overlap = (minDist - dist) / 2;
    a.x -= nx * overlap; a.y -= ny * overlap;
    b.x += nx * overlap; b.y += ny * overlap;

    const rvx = b.vx - a.vx, rvy = b.vy - a.vy;
    const velAlongNormal = rvx * nx + rvy * ny;
    if(velAlongNormal > 0) return; // already separating

    const impulse = -(1 + BALL_RESTITUTION) * velAlongNormal / 2; // equal mass
    a.vx -= impulse * nx; a.vy -= impulse * ny;
    b.vx += impulse * nx; b.vy += impulse * ny;
  }

  function simulate(dt){
    const MAX_SUB = 1 / 240;
    let remaining = dt;
    // guard against absurd dt
    if(remaining > 0.25) remaining = 0.25;
    while(remaining > 1e-9){
      const h = Math.min(MAX_SUB, remaining);
      substep(h);
      remaining -= h;
    }
  }

  // ---------------------------------------------------------------
  // Drawing
  // ---------------------------------------------------------------
  function roundRect(c, x, y, w, h, r){
    c.beginPath();
    c.moveTo(x + r, y);
    c.arcTo(x + w, y, x + w, y + h, r);
    c.arcTo(x + w, y + h, x, y + h, r);
    c.arcTo(x, y + h, x, y, r);
    c.arcTo(x, y, x + w, y, r);
    c.closePath();
  }

  function drawBall(b, i){
    const sx = b.x + RAIL, sy = b.y + RAIL;
    ctx.beginPath();
    ctx.fillStyle = b.cue ? '#f7f7f2' : BALL_COLORS[i % BALL_COLORS.length];
    ctx.arc(sx, sy, R, 0, Math.PI * 2);
    ctx.fill();
    ctx.lineWidth = 1;
    ctx.strokeStyle = 'rgba(0,0,0,0.45)';
    ctx.stroke();

    // shine
    const g = ctx.createRadialGradient(sx - R*0.4, sy - R*0.4, 1, sx, sy, R);
    g.addColorStop(0, 'rgba(255,255,255,0.55)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(sx, sy, R, 0, Math.PI * 2);
    ctx.fill();

    if(!b.cue){
      ctx.fillStyle = '#fff';
      ctx.font = 'bold ' + Math.round(R*0.85) + 'px sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(String((i % 15) + 1), sx, sy);
    }
  }

  function drawAim(cueBall, dragPos){
    const sx = cueBall.x + RAIL, sy = cueBall.y + RAIL;
    const dx = cueBall.x - dragPos.x, dy = cueBall.y - dragPos.y;
    const dist = Math.hypot(dx, dy);
    if(dist < 1) return;
    const nx = dx / dist, ny = dy / dist;
    const power = Math.min(dist, MAX_DRAG);

    ctx.save();
    // forward aim line
    ctx.strokeStyle = 'rgba(255,255,255,0.85)';
    ctx.lineWidth = 2;
    ctx.setLineDash([6,6]);
    ctx.beginPath();
    ctx.moveTo(sx, sy);
    ctx.lineTo(sx + nx*320, sy + ny*320);
    ctx.stroke();
    ctx.setLineDash([]);

    // cue stick behind ball
    const stickStart = power + 26;
    const stickEnd = power + 150;
    ctx.strokeStyle = '#caa06a';
    ctx.lineWidth = 7;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(sx - nx*stickStart, sy - ny*stickStart);
    ctx.lineTo(sx - nx*stickEnd, sy - ny*stickEnd);
    ctx.stroke();

    // power bar
    const pct = power / MAX_DRAG;
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(RAIL, canvas.height - 20, W, 10);
    ctx.fillStyle = pct > 0.75 ? '#ff4d4d' : (pct > 0.4 ? '#ffd24d' : '#7dff7d');
    ctx.fillRect(RAIL, canvas.height - 20, W * pct, 10);

    ctx.restore();
  }

  function draw(){
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // wooden rail
    const railGrad = ctx.createLinearGradient(0,0,canvas.width,canvas.height);
    railGrad.addColorStop(0, '#6b3c17');
    railGrad.addColorStop(1, '#432407');
    ctx.fillStyle = railGrad;
    roundRect(ctx, 0, 0, canvas.width, canvas.height, 20);
    ctx.fill();

    // felt
    ctx.fillStyle = '#0c7043';
    ctx.fillRect(RAIL, RAIL, W, H);
    const feltShade = ctx.createRadialGradient(
      RAIL + W/2, RAIL + H/2, 40, RAIL + W/2, RAIL + H/2, W*0.7
    );
    feltShade.addColorStop(0, 'rgba(255,255,255,0.05)');
    feltShade.addColorStop(1, 'rgba(0,0,0,0.18)');
    ctx.fillStyle = feltShade;
    ctx.fillRect(RAIL, RAIL, W, H);

    ctx.strokeStyle = 'rgba(0,0,0,0.4)';
    ctx.lineWidth = 4;
    ctx.strokeRect(RAIL, RAIL, W, H);

    // pockets
    for(const p of POCKETS){
      const px = p.x + RAIL, py = p.y + RAIL;
      const g = ctx.createRadialGradient(px, py, 1, px, py, POCKET_R);
      g.addColorStop(0, '#000');
      g.addColorStop(1, '#151515');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.arc(px, py, POCKET_R, 0, Math.PI*2);
      ctx.fill();
    }

    // balls
    for(let i = 0; i < balls.length; i++){
      const b = balls[i];
      if(b.potted) continue;
      drawBall(b, i);
    }

    if(dragging && dragPos){
      const cueBall = balls.find(b => b.cue && !b.potted);
      if(cueBall) drawAim(cueBall, dragPos);
    }
  }

  // ---------------------------------------------------------------
  // Mouse interaction
  // ---------------------------------------------------------------
  let dragging = false;
  let dragPos = null;

  function getPlayfieldPos(evt){
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const cx = (evt.clientX - rect.left) * scaleX;
    const cy = (evt.clientY - rect.top) * scaleY;
    return { x: cx - RAIL, y: cy - RAIL };
  }

  function ballsMoving(){
    return balls.some(b => !b.potted && Math.hypot(b.vx, b.vy) > 2);
  }

  canvas.addEventListener('mousedown', (e) => {
    if(ballsMoving()) return;
    const pos = getPlayfieldPos(e);
    const cueBall = balls.find(b => b.cue && !b.potted);
    if(!cueBall) return;
    const d = Math.hypot(pos.x - cueBall.x, pos.y - cueBall.y);
    if(d <= R * 3){
      dragging = true;
      dragPos = pos;
    }
  });

  window.addEventListener('mousemove', (e) => {
    if(!dragging) return;
    dragPos = getPlayfieldPos(e);
  });

  window.addEventListener('mouseup', () => {
    if(!dragging) return;
    dragging = false;
    const cueBall = balls.find(b => b.cue && !b.potted);
    if(cueBall && dragPos){
      const dx = cueBall.x - dragPos.x;
      const dy = cueBall.y - dragPos.y;
      const rawDist = Math.hypot(dx, dy);
      if(rawDist > 3){
        const clamped = Math.min(rawDist, MAX_DRAG);
        const speed = clamped * POWER_SCALE;
        const nx = dx / rawDist, ny = dy / rawDist;
        sim.shoot(nx * speed, ny * speed);
      }
    }
    dragPos = null;
  });

  // touch support
  canvas.addEventListener('touchstart', (e) => {
    if(e.touches.length !== 1) return;
    if(ballsMoving()) return;
    const t = e.touches[0];
    const pos = getPlayfieldPos(t);
    const cueBall = balls.find(b => b.cue && !b.potted);
    if(!cueBall) return;
    const d = Math.hypot(pos.x - cueBall.x, pos.y - cueBall.y);
    if(d <= R * 4){
      dragging = true;
      dragPos = pos;
      e.preventDefault();
    }
  }, {passive:false});

  window.addEventListener('touchmove', (e) => {
    if(!dragging) return;
    const t = e.touches[0];
    dragPos = getPlayfieldPos(t);
    e.preventDefault();
  }, {passive:false});

  window.addEventListener('touchend', () => {
    if(!dragging) return;
    dragging = false;
    const cueBall = balls.find(b => b.cue && !b.potted);
    if(cueBall && dragPos){
      const dx = cueBall.x - dragPos.x;
      const dy = cueBall.y - dragPos.y;
      const rawDist = Math.hypot(dx, dy);
      if(rawDist > 3){
        const clamped = Math.min(rawDist, MAX_DRAG);
        const speed = clamped * POWER_SCALE;
        const nx = dx / rawDist, ny = dy / rawDist;
        sim.shoot(nx * speed, ny * speed);
      }
    }
    dragPos = null;
  });

  // ---------------------------------------------------------------
  // Animation loop
  // ---------------------------------------------------------------
  let running = true;
  let lastTime = null;

  function loop(ts){
    if(!running) return;
    if(lastTime === null) lastTime = ts;
    const dt = Math.min((ts - lastTime) / 1000, 0.05);
    lastTime = ts;
    simulate(dt);
    draw();
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);

  // ---------------------------------------------------------------
  // Public sim API
  // ---------------------------------------------------------------
  const sim = {
    W: W,
    H: H,
    R: R,
    reset: function(inputBalls){
      balls = inputBalls.map(makeBall);
      draw();
    },
    step: function(dt){
      simulate(dt);
      draw();
    },
    state: function(){
      return balls.map(b => ({
        x: b.x, y: b.y,
        vx: b.vx, vy: b.vy,
        potted: b.potted,
        cue: b.cue
      }));
    },
    shoot: function(vx, vy){
      const cueBall = balls.find(b => b.cue && !b.potted);
      if(cueBall){
        cueBall.vx = vx;
        cueBall.vy = vy;
      }
    },
    pause: function(){
      running = false;
    },
    resume: function(){
      if(running) return;
      running = true;
      lastTime = null;
      requestAnimationFrame(loop);
    }
  };

  window.sim = sim;

  // ---------------------------------------------------------------
  // Rack / reset
  // ---------------------------------------------------------------
  function standardRack(){
    const list = [];
    list.push({ x: W * 0.25, y: H / 2, cue: true });

    const apexX = W * 0.68, apexY = H / 2;
    for(let row = 0; row < 5; row++){
      for(let col = 0; col <= row; col++){
        const x = apexX + row * R * Math.sqrt(3);
        const y = apexY + (col - row / 2) * 2 * R;
        list.push({ x, y });
      }
    }
    sim.reset(list);
    document.getElementById('status').textContent = 'Table racked. Drag the cue ball to shoot!';
  }

  document.getElementById('resetBtn').addEventListener('click', standardRack);

  // initial rack
  standardRack();

})();
</script>
</body>
</html>
